#!/usr/bin/env python3
"""
check_codegen_drift.py — guard the generated-vs-hand-written boundary (see AGENTS.md, section 2).

Offline mode (default, no network, safe for every PR):
  * ``controllers.json`` / ``models.json`` parse, carry ``meta.warning`` ("DO NOT EDIT ..."),
    pin ``core_ref`` / ``plugins_ref`` and have ``meta.total_*`` that match their contents.
  * The generators still emit the sentinels (``generate_wrappers.SENTINEL``, ``WARNING`` in
    ``generate_spec`` / ``generate_models``).
  * Any generated Python wrapper in the tree (``{modules,states}/opnsense_*.py``) starts with the
    sentinel header, and no other Python file claims to be generated.

Regenerate mode (``--regenerate``, needs ``git`` + network unless local clones are given):
  Re-runs ``generate_spec.py`` and ``generate_models.py`` at the refs pinned in the committed
  ``meta`` into a temp dir and fails if the result differs from the committed JSON. The volatile
  ``meta.generated_at`` timestamp is ignored, so a clean tree is a deterministic ``exit 0``.
  This is the byte-exact equivalent of ``git diff --exit-code`` after running the generators.

Usage:
  python tools/check_codegen_drift.py
  python tools/check_codegen_drift.py --regenerate
  python tools/check_codegen_drift.py --regenerate --core ~/src/core --plugins ~/src/plugins
  nox -s codegen_drift
"""

from __future__ import annotations

import argparse
import importlib.util
import json
import pathlib
import subprocess
import sys
import tempfile
from typing import Any

ROOT = pathlib.Path(__file__).resolve().parent.parent
TOOLS = ROOT / "tools"
PKG = ROOT / "src" / "saltext" / "opnsense"
UTILS = PKG / "utils"

SENTINEL_FIRST_LINE = "# WARNING: DO NOT EDIT THIS FILE DIRECTLY."
GENERATED_PY_GLOBS = ("modules/opnsense_*.py", "states/opnsense_*.py")
VOLATILE_META = ("generated_at",)
MAX_DIFF_LINES = 25


def _load_tool(name: str) -> Any:
    spec = importlib.util.spec_from_file_location(f"_codegen_{name}", TOOLS / f"{name}.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _load_json(path: pathlib.Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _rel(path: pathlib.Path) -> str:
    try:
        return str(path.relative_to(ROOT))
    except ValueError:
        return str(path)


def _meta_errors(label: str, data: dict[str, Any], expected: dict[str, int]) -> list[str]:
    errors: list[str] = []
    meta = data.get("meta")
    if not isinstance(meta, dict):
        return [f"{label}: missing meta object"]
    if not str(meta.get("warning", "")).startswith("DO NOT EDIT"):
        errors.append(f"{label}: meta.warning must start with 'DO NOT EDIT' (re-run the generator)")
    for ref in ("core_ref", "plugins_ref"):
        if not meta.get(ref):
            errors.append(f"{label}: meta.{ref} is empty")
    for key, want in expected.items():
        if meta.get(key) != want:
            errors.append(f"{label}: meta.{key}={meta.get(key)!r} but contents give {want}")
    return errors


def check_json() -> list[str]:
    errors: list[str] = []
    ctrl = _load_json(UTILS / "controllers.json")
    mods = ctrl.get("modules", {})
    errors += _meta_errors(
        "controllers.json",
        ctrl,
        {
            "total_modules": len(mods),
            "total_controllers": sum(len(c) for c in mods.values()),
            "total_actions": sum(len(a) for c in mods.values() for a in c.values()),
        },
    )
    models = _load_json(UTILS / "models.json")
    mm = models.get("models", {})
    errors += _meta_errors(
        "models.json",
        models,
        {
            "total_modules": len(mm),
            "total_models": sum(len(m) for m in mm.values()),
            "total_arrays": sum(len(a) for m in mm.values() for a in m.values()),
        },
    )
    return errors


def check_generators() -> list[str]:
    errors: list[str] = []
    header = _load_tool("generate_wrappers").HEADER
    if not header.startswith(SENTINEL_FIRST_LINE):
        errors.append("tools/generate_wrappers.py: HEADER must start with the sentinel")
    for name in ("generate_spec", "generate_models"):
        if not str(getattr(_load_tool(name), "WARNING", "")).startswith("DO NOT EDIT"):
            errors.append(f"tools/{name}.py: WARNING must start with 'DO NOT EDIT'")
    return errors


def check_generated_python() -> list[str]:
    errors: list[str] = []
    generated = {p for pattern in GENERATED_PY_GLOBS for p in PKG.glob(pattern)}
    for path in sorted(PKG.rglob("*.py")):
        if path.name == "_version.py":
            continue
        first = path.read_text(encoding="utf-8", errors="ignore").split("\n", 1)[0]
        has_sentinel = first.strip() == SENTINEL_FIRST_LINE
        if path in generated and not has_sentinel:
            errors.append(f"{_rel(path)}: generated wrapper is missing the sentinel header")
        elif path not in generated and has_sentinel:
            errors.append(f"{_rel(path)}: hand-written file must not carry the generated sentinel")
    return errors


def run_offline() -> list[str]:
    return check_json() + check_generators() + check_generated_python()


def _normalized(data: dict[str, Any]) -> dict[str, Any]:
    out = dict(data)
    out["meta"] = {k: v for k, v in data.get("meta", {}).items() if k not in VOLATILE_META}
    return out


def _leaves(obj: Any, prefix: str = "") -> dict[str, str]:
    if isinstance(obj, dict):
        flat: dict[str, str] = {}
        for key, value in obj.items():
            flat.update(_leaves(value, f"{prefix}/{key}"))
        return flat
    return {prefix: json.dumps(obj, sort_keys=True)}


def _describe_drift(label: str, committed: dict[str, Any], fresh: dict[str, Any]) -> list[str]:
    old, new = _leaves(committed), _leaves(fresh)
    lines = [f"{label}: committed file differs from regenerated output"]
    for key in sorted(old.keys() - new.keys()):
        lines.append(f"  - only committed: {key}")
    for key in sorted(new.keys() - old.keys()):
        lines.append(f"  + only regenerated: {key}")
    for key in sorted(k for k in old.keys() & new.keys() if old[k] != new[k]):
        lines.append(f"  ~ changed: {key}")
    if len(lines) > MAX_DIFF_LINES:
        extra = len(lines) - MAX_DIFF_LINES
        lines = lines[:MAX_DIFF_LINES] + [f"  ... {extra} more"]
    return lines


def _run(cmd: list[str]) -> None:
    print(f"$ {' '.join(cmd)}")
    subprocess.run(cmd, check=True, cwd=ROOT, stdout=subprocess.DEVNULL)


def run_regenerate(args: argparse.Namespace) -> list[str]:
    ctrl_path, models_path = UTILS / "controllers.json", UTILS / "models.json"
    committed_ctrl, committed_models = _load_json(ctrl_path), _load_json(models_path)
    meta = committed_ctrl["meta"]
    core_ref = args.core_ref or meta["core_ref"]
    plugins_ref = args.plugins_ref or meta["plugins_ref"]

    with tempfile.TemporaryDirectory(prefix="opnsense-drift-") as scratch:
        work = pathlib.Path(args.tmp_dir or scratch)
        work.mkdir(parents=True, exist_ok=True)
        fresh_ctrl_path, fresh_models_path = (
            pathlib.Path(scratch) / "c.json",
            pathlib.Path(scratch) / "m.json",
        )
        refs = ["--core-ref", core_ref, "--plugins-ref", plugins_ref]
        spec_cmd = [sys.executable, str(TOOLS / "generate_spec.py"), *refs]
        spec_cmd += ["--output", str(fresh_ctrl_path), "--tmp-dir", str(work)]
        if args.core:
            spec_cmd += ["--local-core", args.core]
        if args.plugins:
            spec_cmd += ["--local-plugins", args.plugins]
        _run(spec_cmd)
        models_cmd = [sys.executable, str(TOOLS / "generate_models.py"), *refs]
        models_cmd += ["--core", args.core or str(work / "core")]
        models_cmd += ["--plugins", args.plugins or str(work / "plugins")]
        models_cmd += ["--output", str(fresh_models_path)]
        _run(models_cmd)
        fresh_ctrl, fresh_models = _load_json(fresh_ctrl_path), _load_json(fresh_models_path)

    errors: list[str] = []
    for label, committed, fresh in (
        ("controllers.json", committed_ctrl, fresh_ctrl),
        ("models.json", committed_models, fresh_models),
    ):
        if _normalized(committed) != _normalized(fresh):
            errors += _describe_drift(label, _normalized(committed), _normalized(fresh))
    return errors


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--regenerate", action="store_true", help="re-run generators and compare")
    parser.add_argument("--core-ref", help="override meta.core_ref (default: committed value)")
    parser.add_argument("--plugins-ref", help="override meta.plugins_ref (default: committed)")
    parser.add_argument("--core", help="local opnsense/core checkout (skips clone)")
    parser.add_argument("--plugins", help="local opnsense/plugins checkout (skips clone)")
    parser.add_argument("--tmp-dir", help="directory for upstream clones (default: temporary)")
    args = parser.parse_args(argv)

    errors = run_offline()
    if args.regenerate and not errors:
        errors = run_regenerate(args)
    if errors:
        print("\n".join(errors), file=sys.stderr)
        print(f"FAIL: codegen drift ({len(errors)} finding(s))", file=sys.stderr)
        return 1
    print("PASS: codegen drift" + (" (regenerated, no drift)" if args.regenerate else " (offline)"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
